 class="primary" id="loginbutton" type="submit">Iniciar sesión →</button><button class="secondary" type="button" id="change-password-login" style="width:100%;margin-top:12px">Cambiar contraseña</button><p id="loginerror" class="hint" role="alert"></p><p class="hint">Estudiantes: ingresa con tu usuario y contraseña para registrar tu propia asistencia sin huella.</p></form></div></section><div id="app"><aside class="sidebar"><div class="logo"><img class="institution-logo" src="assets/logo-iestpan.jpg" alt="Logo del IESTP Alfred Nobel, Huariaca, Pasco">Nobel<span style="color:#67e6d0">.</span></div><div class="eyebrow">Espacio de trabajo</div><button class="nav active" data-page="dashboard">▦ <span>Inicio</span></button><button class="nav" data-page="students">♙ <span>Estudiantes</span></button><button class="nav" data-page="teachers">♧ <span>Docentes y clases</span></button><button class="nav" data-page="attendance">▤ <span>Asistencia</span></button><button class="nav" data-page="scan">◎ <span>Registrar asistencia</span></button><button class="nav" data-page="devices">▣ <span>Dispositivos</span></button><button class="nav" data-page="reports">↗ <span>Reportes</span></button><button class="nav" data-page="users">♙ <span>Usuarios y permisos</span></button><button class="nav" data-page="audit">▤ <span>Bitácora</span></button><div class="sidebar-bottom"><strong style="color:white">Instituto Alfred Nobel</strong><p>Huariaca · Educación superior</p><button id="logout" style="background:none;color:#9db8cb;padding:8px 0">↪ Cerrar sesión</button></div></aside><main class="main"><header class="topbar"><div class="profile"><img class="header-logo" src="assets/logo-iestpan.jpg" alt="Logo oficial Alfred Nobel"><div><strong>IESTP ALFRED NOBEL</strong><br><span class="muted small">SCAE · Control de asistencia estudiantil</span></div></div><div class="profile"><button type="button" class="secondary" id="change-password-account">Cambiar mi contraseña</button><span class="badge">● Base de datos</span><span class="avatar">AD</span><div class="small"><strong id="username">Usuario</strong><br><span class="muted" id="rolename">Cuenta institucional</span></div></div></header><div class="content" id="content"></div><div class="notice">Datos guardados en base de datos · Permisos por usuario · Lectores físicos pendientes de integración</div></main></div><script>
const programs=['APSTI','ENFERMERÍA','FISIOTERAPIA'];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const students=[],teachers=[];let sessionToken='';try{sessionToken=sessionStorage.getItem('nobel-local-session')||''}catch{}let me=null,users=[],audit=[],attendance=[],myClasses=[],serverTime='',enrollments=[],teacherAccounts=[],availableClasses=[],enrolledClasses=[];const can=p=>me?.permissions.includes(p);const roleNames={admin:'Administrador',gestor:'Gestor académico',docente:'Docente',consulta:'Consulta',estudiante:'Estudiante'};async function api(payload){const r=await fetch('api.php?route=data',payload?{method:'POST',headers:{'Content-Type':'application/json',...(sessionToken?{Authorization:'Bearer '+sessionToken}:{})},body:JSON.stringify(payload)}:{cache:'no-store',headers:sessionToken?{Authorization:'Bearer '+sessionToken}:{}});let d;try{d=await r.json()}catch{throw Error('El servidor no devolvió una respuesta válida. Abre el sistema en una pestaña nueva y vuelve a intentar.')}if(r.status===401){sessionToken='';try{sessionStorage.removeItem('nobel-local-session')}catch{}$('app').style.display='none';$('login').style.display='grid';$('loginerror').textContent='Tu sesión venció. Ingresa nuevamente.';}if(!r.ok)throw Error(d.error||'No fue posible completar la operación.');return d}async function reload(){const d=await api();students.splice(0,students.length,...d.students);teachers.splice(0,teachers.length,...d.teachers);me=d.me;users=d.users;audit=d.audit;attendance=d.attendance;myClasses=d.classes||[];serverTime=d.serverTime||'';enrollments=d.enrollments||[];teacherAccounts=d.teacherAccounts||[];availableClasses=d.availableClasses||[];enrolledClasses=d.enrolledClasses||[];document.querySelectorAll('[data-page]').forEach(b=>{b.hidden=(me.role==='estudiante'&&!['dashboard','attendance'].includes(b.dataset.page))||(b.dataset.page==='users'&&!can('users'))||(b.dataset.page==='audit'&&!can('audit'))||(b.dataset.page==='scan'&&!can('attendance'));});$('username').textContent=me.name;$('rolename').textContent=roleNames[me.role];}async function mutate(payload){const result=await api(payload);if(result.reauth){signedOut('Datos actualizados. Ingresa nuevamente con tu correo y contraseña.');return result}try{await reload();render(current)}catch(e){if(!result.credentials)throw e;sessionToken='';try{sessionStorage.removeItem('nobel-local-session')}catch{}$('app').style.display='none';$('login').style.display='grid';$('loginerror').textContent='Credenciales restablecidas. Inicia sesión con los nuevos datos.';}if(result.credentials)showCredentials(result.credentials);return result}let current='dashboard',method='Facial';const $=id=>document.getElementById(id);const initials=n=>n.split(' ').slice(0,2).map(w=>w[0]).join('');const date=()=>new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Lima'}).format(new Date());const pill=s=>`<span class="status ${s==='Tardanza'?'late':s==='Falta'?'absent':''}">${s}</span>`;function toast(t){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),4500)}async function enter(){try{await reload();$('login').style.display='none';$('app').style.display='block';render('dashboard')}catch(e){$('loginerror').textContent=e.message}}$('loginform').onsubmit=async e=>{e.preventDefault();$('loginbutton').disabled=true;$('loginerror').textContent='Verificando credenciales…';try{const r=await fetch('api.php?route=auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})});const d=await r.json();if(!r.ok)throw Error(d.error);sessionToken=d.sessionToken;try{sessionStorage.setItem('nobel-local-session',sessionToken)}catch{}$('password').value='';await enter()}catch(err){$('loginerror').textContent=err.message}finally{$('loginbutton').disabled=false}};$('logout').onclick=async()=>{await fetch('api.php?route=auth',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+sessionToken},body:JSON.stringify({action:'logout'})});me=null;sessionToken='';try{sessionStorage.removeItem('nobel-local-session')}catch{}$('app').style.display='none';$('login').style.display='grid';$('loginerror').textContent='Sesión cerrada.';};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page));function head(title,desc,action=''){return `<div class="pagehead"><div class="page-brand"><img src="assets/logo-iestpan.jpg" alt="Logo Alfred Nobel"><div><div class="eyebrow muted">Alfred Nobel / Gestión académica</div><h1>${title}</h1><div class="muted">${desc}</div></div></div>${action||`<button class="secondary">${date()}</button>`}</div>`}function table(list,roster=false){return `<div class="tablewrap"><table><thead><tr><th>Estudiante</th><th>Código</th><th>Programa</th><th>${roster?'Semestre':'Ingreso'}</th><th>${roster?'Registro':'Método'}</th><th>Estado</th>${roster&&can('delete')&&can('students')?'<th>Acción</th>':''}</tr></thead><tbody>${list.map(s=>`<tr><td><div class="person"><span class="avatar">${esc(initials(s.name))}</span><strong>${esc(s.name)}</strong></div></td><td class="muted">${esc(s.id)}</td><td>${s.program}</td><td>${roster?s.semester:s.time}</td><td>${roster?'Sin enrolamiento real':s.method}</td><td>${pill(s.status)}</td>${roster&&can('delete')&&can('students')?`<td><button class="teacher-action" data-editstudent="${esc(s.id)}">Editar</button> <button class="danger" data-delstudent="${esc(s.id)}">Eliminar</button></td>`:''}</tr>`).join('')||'<tr><td colspan="6" class="empty">No se encontraron estudiantes.</td></tr>'}</tbody></table></div>`}function devices(){return `<div class="device"><span class="device-icon">◎</span><div><strong>Terminal facial · Entrada principal</strong><p>Modelo por definir · Conexión pendiente</p></div><span class="badge" style="background:#fff2db;color:#ac7c2d">Sin conectar</span></div><div class="device"><span class="device-icon">◉</span><div><strong>Lector de huella · Acceso 02</strong><p>Modelo por definir · Conexión pendiente</p></div><span class="badge" style="background:#fff2db;color:#ac7c2d">Sin conectar</span></div>`}function exportCSV(){const csv='\ufeffCódigo,Estudiante,Programa,Semestre,Ingreso,Método,Estado\n'+students.map(s=>[s.id,s.name,s.program,s.semester,s.time,s.method,s.status].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='asistencia_nobel.csv';a.click();URL.revokeObjectURL(a.href);toast('Reporte exportado.')}function render(page){current=page;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const present=students.filter(s=>s.status==='Presente').length,late=students.filter(s=>s.status==='Tardanza').length;let html='';if(me.role==='estudiante'){renderStudent(page);return}if(page==='users'){html=userPage()}else if(page==='audit'){html=auditPage()}else if(page==='teachers'){html=teacherPage()}else if(page==='dashboard'){html=head('Una mirada a tu jornada','El seguimiento de tus estudiantes, más cerca de ti.')+`<div class="banner"><div><div class="eyebrow" style="color:#67e6d0">Asistencia inteligente</div><h2>Menos espera. Más tiempo para aprender.</h2><p>Registro manual del personal y asistencia desde la cuenta del estudiante.</p><button class="primary" id="openscan">Abrir registro de asistencia →</button></div><div class="scan-art">◎</div></div><div class="stats">${[['Estudiantes',students.length,'Padrón institucional','♙'],['Presentes',present,'Ingresos a tiempo','✓'],['Tardanzas',late,'Requieren seguimiento','◷'],['Faltas',students.filter(s=>s.status==='Falta').length,students.filter(s=>s.status==='Pendiente').length+' pendientes','!']].map(([t,v,d,i])=>`<div class="stat"><div class="stat-top"><span class="muted">${t}</span><span class="stat-icon">${i}</span></div><div class="value">${v}</div><div class="delta">${d}</div></div>`).join('')}</div><div class="grid"><div class="card"><div class="card-header"><h3>Estado de asistencia</h3><span class="muted small">Registros actuales</span></div><div class="bars">${[present,late,students.filter(s=>s.status==='Falta').length].map((v,i)=>`<div class="bar-group"><span class="small muted">${v}</span><div class="bar" style="height:${students.length?v/students.length*140:0}px"></div><span class="bar-label">${['Presentes','Tardanzas','Faltas'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-header"><h3>Puntos de registro</h3><span class="muted">02</span></div>${devices()}<button class="secondary" id="opendevices" style="width:100%;margin-top:15px">Ver dispositivos →</button></div></div><div class="card"><div class="card-header"><h3>Últimos registros</h3><button class="secondary" id="allattendance">Ver todos →</button></div>${table(students.slice(0,5))}<div class="foot"><span>Información guardada en la base de datos</span><span>Marcaciones registradas</span></div></div>`}else if(page==='students'||page==='attendance'){html=head(page==='students'?'Estudiantes':'Control de asistencia',page==='students'?'Padrón estudiantil. Las cuentas y matrículas se administran por separado.':'Consulta los ingresos y el estado de cada estudiante.',`<div class="actions">${page==='students'&&can('students')?'<button class="primary" id="addstudent">+ Agregar estudiante</button>':''}<button class="secondary" id="export">↓ Exportar CSV</button></div>`)+`<div class="card"><div class="toolbar"><input class="search" id="search" aria-label="Buscar estudiante" placeholder="Buscar por nombre o código…"><select id="program" aria-label="Filtrar programa"><option value="">Todos los programas</option>${programs.map(p=>`<option>${p}</option>`).join('')}</select><select id="status" aria-label="Filtrar estado"><option value="">Todos los estados</option><option>Presente</option><option>Tardanza</option><option>Falta</option><option>Pendiente</option></select></div>${page==='attendance'?`<div class="toolbar"><label>Clase<select id="filterclass"><option value="">Todas las clases</option>${teachers.map(t=>`<option value="${esc(t.id)}">${esc(t.subject+' · '+t.name)}</option>`).join('')}</select></label><label>Fecha de clase<input id="filterdate" type="date"></label></div>`:''}<div id="rows">${page==='students' ?table(students,true):attendanceTable(attendance)}</div><div class="foot"><span id="count">${students.length} estudiantes</span><span>Registros de la base de datos</span></div></div>`}else if(page==='scan'){html=head('Registro de asistencia','Registra una marcación manual mientras se integran los lectores.')+`<div class="scan-layout"><div class="scanner"><div class="eyebrow" style="color:#67e6d0">Registro institucional</div><div class="scan-frame">◎</div><h2>Huella y rostro</h2><p style="color:#a4c4d2">La integración física requiere confirmar el modelo del equipo.</p><span class="badge">Sin captura biométrica</span></div><div class="card"><h3>Registrar asistencia manual</h3><form class="form" id="scanform"><label for="classselect">Clase de hoy</label><select id="classselect" required>${teachers.map(t=>`<option value="${esc(t.id)}">${esc(t.subject+' · '+t.name+' · '+t.day)}</option>`).join('')}</select><label for="studentselect">Estudiante matriculado</label><select id="studentselect" required>${students.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select><label for="attendancecode">Código de verificación del estudiante</label><input id="attendancecode" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="off" placeholder="Código de asistencia de 6 dígitos"><label for="resultstatus">Estado</label><select id="resultstatus"><option>Presente</option><option>Tardanza</option><option>Falta</option></select><button class="primary" ${students.length?'':'disabled'}>Guardar asistencia →</button></form><div class="demo">Ingresa el código de asistencia del estudiante. El registro guardará tu usuario, fecha y hora.</div></div></div>`}else if(page==='devices'){html=head('Dispositivos','Prepara los puntos de ingreso del instituto.')+`<div class="card">${devices()}</div><div class="card" style="margin-top:22px"><h3>Configuración para la siguiente etapa</h3><p class="muted" style="line-height:1.9">La conexión requiere confirmar marca, modelo y mecanismo de integración del terminal. Se podrá definir la sincronización de estudiantes y marcaciones, así como el funcionamiento ante pérdida de conexión.</p><span class="badge">Estado: planificación técnica</span></div>`}else{html=head('Reportes','Transforma los registros en información para el seguimiento.')+`<div class="report-grid">${[['▤','Registro detallado','Descarga el padrón con el estado, hora y método de cada ingreso.','csv'],['↗','Resumen de asistencia','Visualiza los indicadores actuales de la jornada.','dashboard'],['♙','Seguimiento estudiantil','Consulta estudiantes y filtra por programa y estado.','students']].map(([i,t,d,a])=>`<div class="card"><span class="stat-icon">${i}</span><h3>${t}</h3><p>${d}</p><button class="primary" data-report="${a}">${a==='csv'?'Descargar CSV':'Abrir consulta'} →</button></div>`).join('')}</div>`}$('content').innerHTML=html;if($('addstudent'))$('addstudent').onclick=()=>studentModal();if($('addteacher'))$('addteacher').onclick=()=>teacherModal();if($('teachersearch'))$('teachersearch').oninput=()=>teacherRows();document.querySelectorAll('[data-editteacher]').forEach(b=>b.onclick=()=>teacherModal(Number(b.dataset.editteacher)));window.scrollTo(0,0);if($('openscan')){ $('openscan').hidden=!can('attendance');$('openscan').onclick=()=>render('scan');}if($('opendevices'))$('opendevices').onclick=()=>render('devices');if($('allattendance'))$('allattendance').onclick=()=>render('attendance');if($('export'))$('export').onclick=exportCSV;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>b.dataset.report==='csv'?exportCSV():render(b.dataset.report));if($('search')){const filter=()=>{const q=$('search').value.toLowerCase(),p=$('program').value,s=$('status').value,list=students.filter(x=>(x.name.toLowerCase().includes(q)||x.id.toLowerCase().includes(q))&&(!p||p===x.program)&&(!s||s===x.status));$('rows').innerHTML=page==='students'?table(list,true):attendanceTable(attendance.filter(a=>(a.name.toLowerCase().includes(q)||a.student_id.toLowerCase().includes(q))&&(!p||p===a.program)&&(!s||s===a.status)&&(!$('filterclass')?.value||a.teacher_id===$('filterclass').value)&&(!$('filterdate')?.value||a.class_date===$('filterdate').value)));bindDeletes();$('count').textContent=list.length+' estudiantes'};$('search').oninput=filter;$('program').onchange=filter;$('status').onchange=filter;if($('filterclass'))$('filterclass').onchange=filter;if($('filterdate'))$('filterdate').onchange=filter;}if($('scanform')){const updateRoster=()=>{const list=students.filter(s=>enrollments.some(e=>e.teacher_id===$('classselect').value&&e.student_id===s.id));$('studentselect').innerHTML=list.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$('scanform').querySelector('button').disabled=!list.length;};$('classselect').onchange=updateRoster;updateRoster();$('scanform').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{await mutate({action:'attendance.create',studentId:$('studentselect').value,status:$('resultstatus').value,method:'Manual',teacherId:$('classselect').value,code:$('attendancecode').value});toast('Asistencia guardada.')}catch(err){toast(err.message)}finally{btn.disabled=false}}}bindDeletes();if($('adduser'))$('adduser').onclick=()=>userModal();document.querySelectorAll('[data-edituser]').forEach(b=>b.onclick=()=>userModal(b.dataset.edituser));}

function programOptions(selected=''){return programs.map(p=>`<option ${p===selected?'selected':''}>${p}</option>`).join('')}function semesterOptions(selected='I'){return ['I','II','III','IV','V','VI'].map(p=>`<option ${p===selected?'selected':''}>${p}</option>`).join('')}
function modal(title,body,onSubmit){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.className='modal';d.innerHTML=`<div class="modal-header"><img src="assets/logo-iestpan.jpg" alt="Logo Alfred Nobel"><h2>${title}</h2><button class="closemodal" aria-label="Cerrar">×</button></div><div class="modal-body"><form class="form" id="recordform">${body}<div class="actions"><button type="button" class="secondary" id="cancelmodal">Cancelar</button><button class="primary" type="submit">Guardar registro</button></div></form></div>`;document.body.append(d);d.querySelector('.closemodal').onclick=()=>d.close();$('cancelmodal').onclick=()=>d.close();$('recordform').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{if(await onSubmit(new FormData(e.target))!==false)d.close()}catch(err){toast(err.message)}finally{btn.disabled=false}};d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.showModal()}
function studentModal(){
 modal('Agregar estudiante',`<div class="fields"><div class="wide"><label>Nombres y apellidos<input name="name" required maxlength="100" placeholder="Nombre completo del estudiante"></label></div><div><label>Código institucional<input value="Se genera automáticamente al guardar" readonly aria-label="Código institucional. Se genera automáticamente al guardar"></label></div><div><label>DNI (opcional)<input name="dni" pattern="[0-9]{8}" maxlength="8" inputmode="numeric" placeholder="8 dígitos"></label></div><div><label>Programa de estudios<select name="program">${programOptions()}</select></label></div><div><label>Semestre matriculado<select name="semester">${semesterOptions()}</select></label></div><div class="wide"><label style="display:flex;gap:10px;align-items:center"><input type="checkbox" name="enrollBySemester" style="width:auto">Matricular desde administración en todas las clases actuales de este programa y semestre (opcional)</label><div id="semester-class-preview" class="hint" role="status" aria-live="polite"></div></div></div><p class="hint">El código institucional será correlativo (001, 002, 003…) y no cambiará si posteriormente cambia de semestre. También se genera un código de verificación de seis dígitos para el registro del personal; no es la contraseña de acceso del estudiante.</p>`,async f=>{
 const name=f.get('name').trim(),dni=f.get('dni').trim();if(!name){toast('Completa el nombre del estudiante.');return false}if(dni&&students.some(x=>x.dni===dni)){toast('El DNI ya está registrado.');return false}
 await mutate({action:'student.create',name,dni,program:f.get('program'),semester:f.get('semester'),enrollBySemester:f.get('enrollBySemester')==='on'});toast('Estudiante guardado con código institucional automático.');
 });
 const form=$('recordform');const preview=()=>{const list=teachers.filter(t=>t.program===form.elements.program.value&&t.semester===form.elements.semester.value);$('semester-class-preview').textContent=!form.elements.enrollBySemester.checked?'El estudiante elegirá sus clases al ingresar, en Inicio → Clases disponibles para inscribirme. También puedes asignarlas desde Docentes y clases → Matrícula.':list.length?`${list.length} clase(s): ${list.map(t=>t.subject+' ('+t.day+' '+t.start+'–'+t.end+')').join('; ')}`:'No hay clases creadas para este programa y semestre. Se registrará el padrón; deberás matricular al estudiante después de crear sus clases.';};form.elements.program.onchange=preview;form.elements.semester.onchange=preview;form.elements.enrollBySemester.onchange=preview;preview();
}

function editStudentModal(id){
 const s=students.find(x=>x.id===id);if(!s)return;
 modal('Editar estudiante',`<div class="fields"><div class="wide"><label>Código institucional<input value="${esc(s.id)}" readonly aria-label="Código institucional, no modificable"></label></div><div class="wide"><label>Nombres y apellidos<input name="name" required maxlength="100" value="${esc(s.name)}"></label></div><div><label>DNI (opcional)<input name="dni" pattern="[0-9]{8}" maxlength="8" inputmode="numeric" value="${esc(s.dni||'')}"></label></div><div><label>Programa de estudios<select name="program">${programOptions(s.program)}</select></label></div><div><label>Semestre matriculado<select name="semester">${semesterOptions(s.semester)}</select></label></div><div class="wide"><label style="display:flex;gap:10px;align-items:center"><input type="checkbox" name="removeIncompatible" style="width:auto">Si cambio la carrera o semestre, retirar las matrículas que ya no correspondan</label></div></div><p class="hint">El código institucional y las asistencias anteriores se conservan. Si cambias carrera o semestre, el alumno deberá inscribirse en sus nuevas clases. Para retirar matrículas incompatibles debes marcar la opción anterior.</p>`,async f=>{
 await mutate({action:'student.update',id,name:f.get('name').trim(),dni:f.get('dni').trim(),program:f.get('program'),semester:f.get('semester'),removeIncompatible:f.get('removeIncompatible')==='on'});toast('Datos del estudiante actualizados.');
 });
}

function teacherPage(){return head('Docentes y clases','Registra docentes y asigna su programa, semestre y clase.',(can('teachers')||can('own_classes'))?`<button class="primary" id="addteacher">+ Agregar docente / clase</button>`:'')+`<div class="card"><div class="toolbar"><input id="teachersearch" class="search" placeholder="Buscar docente, programa o clase…" aria-label="Buscar docente"></div><p class="hint">Cada clase se vincula con una cuenta docente. Usa Matrícula para seleccionar sus estudiantes. Las clases sin cuenta asignada solo son visibles al personal autorizado.</p><div id="teacherrows">${teacherTable(teachers)}</div></div>`}
function teacherTable(list){return `<div class="tablewrap"><table><thead><tr><th>Docente</th><th>Programa</th><th>Clase / unidad didáctica</th><th>Semestre</th><th>Horario</th><th>Acción</th></tr></thead><tbody>${list.map(t=>`<tr><td><div class="person"><span class="avatar">${esc(initials(t.name))}</span><div><strong>${esc(t.name)}</strong><br><span class="muted">${esc(t.email||'Sin correo')}</span></div></div></td><td>${esc(t.program)}</td><td>${esc(t.subject)}</td><td>${esc(t.semester)}</td><td>${esc(t.day)} · ${esc(t.start)}–${esc(t.end)}</td><td>${(can('teachers')||can('own_classes'))?`<button class="teacher-action" data-editteacher="${teachers.indexOf(t)}">Editar</button>`:''}${can('teachers')?` <button class="teacher-action" data-enroll="${esc(t.id)}">Matrícula</button>`:''}${can('teachers')&&can('delete')?` <button class="danger" data-delteacher="${esc(t.id)}">Eliminar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Aún no hay docentes asignados. Agrega el primero para organizar tus clases.</td></tr>'}</tbody></table></div>`}
function teacherRows(){const q=$('teachersearch').value.toLocaleLowerCase();$('teacherrows').innerHTML=teacherTable(teachers.filter(t=>[t.name,t.program,t.subject].join(' ').toLocaleLowerCase().includes(q)));document.querySelectorAll('[data-editteacher]').forEach(b=>b.onclick=()=>teacherModal(Number(b.dataset.editteacher)));bindDeletes()}
function teacherModal(index=-1){const t=teachers[index]||{name:'',email:'',subject:'',program:'APSTI',semester:'I',day:'Lunes',start:'08:00',end:'10:00'};modal(index<0?'Agregar docente y clase':'Editar docente y clase',`<div class="fields"><div class="wide"><label>Cuenta docente de esta clase<select name="teacherUserId"><option value="">Sin cuenta docente asignada</option>${teacherAccounts.map(u=>`<option value="${esc(u.id)}" ${(t.teacher_user_id===u.id||me.role==='docente'&&me.id===u.id)?'selected':''}>${esc(u.name+' · '+u.email)}</option>`).join('')}</select></label><p class="hint">Crea primero la cuenta con rol Docente en Usuarios y permisos. Al asignarla se utilizan su nombre y correo.</p></div><div class="wide"><label>Nombres y apellidos del docente<input name="name" value="${esc(t.name)}" required maxlength="100"></label></div><div class="wide"><label>Correo (opcional)<input name="email" type="email" value="${esc(t.email)}" maxlength="120"></label></div><div><label>Programa<select name="program">${me.role==='docente'?`<option>${esc(me.program)}</option>`:programOptions(t.program)}</select></label></div><div><label>Semestre<select name="semester">${semesterOptions(t.semester)}</select></label></div><div class="wide"><label>Clase / unidad didáctica<input name="subject" required maxlength="120" value="${esc(t.subject)}" placeholder="Ej. Sistemas Operativos"></label></div><div class="wide"><label>Día<select name="day">${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'].map(d=>`<option ${d===t.day?'selected':''}>${d}</option>`).join('')}</select></label></div><div><label>Hora de inicio<input type="time" name="start" required value="${esc(t.start)}"></label></div><div><label>Hora de fin<input type="time" name="end" required value="${esc(t.end)}"></label></div></div>`,async f=>{const v=Object.fromEntries(f);if(v.teacherUserId){const account=teacherAccounts.find(x=>x.id===v.teacherUserId);if(account){v.name=account.name;v.email=account.email}}v.name=v.name.trim();v.subject=v.subject.trim();v.start=v.start.slice(0,5);v.end=v.end.slice(0,5);if(!v.name||!v.subject){toast('Completa docente y clase.');return false}if(v.end<=v.start){toast('La hora de fin debe ser posterior al inicio.');return false}if(teachers.some((x,i)=>i!==index&&x.name.toLowerCase()===v.name.toLowerCase()&&x.day===v.day&&v.start<x.end&&v.end>x.start)){toast('El docente ya tiene una clase en ese horario.');return false}await mutate({action:'teacher.save',...v,id:index<0?undefined:teachers[index].id});toast('Asignación docente guardada.')});const form=$('recordform');if(me.role==='docente'){form.elements.name.value=me.name;form.elements.email.value=me.email;form.elements.teacherUserId.value=me.id;}form.elements.teacherUserId.onchange=()=>{const u=teacherAccounts.find(x=>x.id===form.elements.teacherUserId.value);if(u){form.elements.name.value=u.name;form.elements.email.value=u.email;}};}

function attendanceTable(list){return `<div class="tablewrap"><table><thead><tr><th>Estudiante</th><th>Programa</th><th>Fecha y hora</th><th>Clase / método</th><th>Estado</th>${can('delete')&&can('attendance')?'<th>Acción</th>':''}</tr></thead><tbody>${list.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.program)}</td><td>${esc(new Date(a.created_at).toLocaleString('es-PE',{timeZone:'America/Lima'}))}</td><td>${esc(a.subject||'Sin clase (registro del personal)')}<br>${esc(a.method)}</td><td>${pill(a.status)}</td>${can('delete')&&can('attendance')?`<td><button class="danger" data-delattendance="${esc(a.id)}">Eliminar</button></td>`:''}</tr>`).join('')||'<tr><td colspan="6" class="empty">Todavía no hay marcaciones registradas.</td></tr>'}</tbody></table></div>`}
function bindDeletes(){document.querySelectorAll('[data-enroll]').forEach(b=>b.onclick=()=>enrollmentModal(b.dataset.enroll));document.querySelectorAll('[data-resetpassword]').forEach(b=>b.onclick=()=>resetPasswordModal(b.dataset.resetpassword));document.querySelectorAll('[data-editstudent]').forEach(b=>b.onclick=()=>editStudentModal(b.dataset.editstudent));for(const [attr,action,message] of [['student','student.delete','Se eliminará el estudiante y todas sus asistencias. Esta acción no se puede deshacer.'],['teacher','teacher.delete','Se eliminará esta asignación de docente y clase.'],['attendance','attendance.delete','Se eliminará esta marcación de asistencia.']])document.querySelectorAll('[data-del'+attr+']').forEach(b=>b.onclick=()=>{const id=b.dataset['del'+attr];modal('Confirmar eliminación',`<p class="policy">${message}</p>`,async()=>{await mutate({action,id});toast('Registro eliminado y acción registrada en bitácora.')});const submit=document.querySelector('dialog [type=submit]');submit.textContent='Eliminar definitivamente';submit.classList.add('danger')})}
function userPage(){return head('Usuarios y permisos','Administra las cuentas autorizadas y su nivel de acceso.',`<button class="primary" id="adduser">+ Crear usuario</button>`)+`<div class="card"><p class="policy">Administrador: control completo. Gestor: estudiantes, clases y asistencias, incluida eliminación. Docente: crea y edita sus clases de su carrera y consulta sus estudiantes inscritos y asistencias. No modifica las marcaciones. Consulta: solo lectura. Estudiante: consulta únicamente sus datos y registra su propia asistencia por clase. El correo es el usuario de acceso. El administrador asigna la contraseña y cada persona puede cambiarla validando la actual.</p><div class="tablewrap"><table><thead><tr><th>Usuario</th><th>Usuario / correo</th><th>Rol</th><th>Programa</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td><strong>${esc(u.email)}</strong><br>${esc(u.email)}</td><td>${roleNames[u.role]}</td><td>${esc(u.program||'Todos')}</td><td>${u.active?'Activo':'Desactivado'} · ${u.linked?'Vinculado':'Pendiente'}</td><td><button class="teacher-action" data-edituser="${esc(u.id)}">Editar permisos</button> <button class="teacher-action" data-resetpassword="${esc(u.id)}">Cambiar contraseña</button></td></tr>`).join('')}</tbody></table></div></div>`}
function userModal(id){
 const u=users.find(x=>x.id===id)||{name:'',email:'',role:'consulta',program:'APSTI',active:1};
 modal(id?'Editar usuario y permisos':'Crear usuario',`<div class="fields"><div class="wide"><label>Nombre<input name="name" required maxlength="100" value="${esc(u.name)}"></label></div><div class="wide"><label>Correo (será el usuario de acceso)<input name="email" type="email" required maxlength="120" value="${esc(u.email)}" ${id?'readonly':''} autocomplete="off"></label></div><div><label>Rol<select name="role">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${u.role===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="account-program"><label>Programa del docente<select name="program">${programOptions(u.program)}</select></label></div><div class="wide" id="account-student"><label>Estudiante del padrón asociado a esta cuenta<select name="studentId"><option value="">Seleccionar estudiante</option>${students.map(x=>`<option value="${esc(x.id)}" ${u.student_id===x.id?'selected':''}>${esc(x.name+' · '+x.program+' · '+x.semester+(x.dni?' · DNI '+x.dni:''))}</option>`).join('')}</select></label><p class="hint">Identifica a la persona que usa esta cuenta. Las clases se asignan aparte mediante Matrícula.</p></div><div><label>Estado<select name="active"><option value="true" ${u.active?'selected':''}>Activo</option><option value="false" ${!u.active?'selected':''}>Desactivado</option></select></label></div>${!id?`<div class="wide"><label>Contraseña asignada por el administrador<input name="newPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label></div><div class="wide"><label>Confirmar contraseña<input name="confirmPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label></div>`:''}</div><p class="hint">Ingresa con tu correo. Contraseña: mínimo 8 caracteres, máximo 72 bytes. Para cambiar una contraseña existente utiliza el botón Cambiar contraseña de la lista de usuarios.</p>`,async f=>{const v=Object.fromEntries(f);await mutate({action:'user.save',...v,id,active:v.active==='true'});toast('Cuenta guardada. El usuario de acceso es su correo.');});
 const form=$('recordform'),role=form.elements.role;
 const update=()=>{const student=role.value==='estudiante';$('account-student').hidden=!student;form.elements.studentId.disabled=!student;form.elements.studentId.required=student;$('account-program').hidden=role.value!=='docente';form.elements.program.disabled=role.value!=='docente';};role.onchange=update;update();
}
function signedOut(message){me=null;sessionToken='';try{sessionStorage.removeItem('nobel-local-session')}catch{}$('app').style.display='none';$('login').style.display='grid';$('password').value='';$('loginerror').textContent=message;}
function passwordModal(){
 const email=me?.email||$('email').value;
 modal('Cambiar mi contraseña',`<label>Correo de acceso<input name="email" type="email" required maxlength="120" value="${esc(email)}" ${me?'readonly':''} autocomplete="username"></label><label>Contraseña actual<input name="password" type="password" required maxlength="200" autocomplete="current-password"></label><label>Nueva contraseña<input name="newPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><label>Confirmar nueva contraseña<input name="confirmPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><p class="hint">Se verifica tu contraseña actual, incluida la asignada por el administrador. Al cambiarla se cerrarán tus sesiones. Si la olvidaste, solicita al administrador que la restablezca.</p>`,async f=>{
  const v=Object.fromEntries(f);if(v.newPassword!==v.confirmPassword)throw Error('Las contraseñas nuevas no coinciden.');
  const response=await fetch('api.php?route=auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'change_password',...v})});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo cambiar la contraseña.');
  $('recordform').reset();signedOut('Contraseña actualizada. Ingresa con tu correo y tu nueva contraseña.');
 });
}
function resetPasswordModal(id){
 const u=users.find(x=>x.id===id);if(!u)return;
 modal('Asignar nueva contraseña',`<p>Cuenta: <strong>${esc(u.email)}</strong></p><label>Nueva contraseña asignada<input name="newPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><label>Confirmar nueva contraseña<input name="confirmPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><p class="hint">La contraseña anterior dejará de funcionar y se cerrarán las sesiones de esta cuenta. Comunica la nueva contraseña a su titular de forma individual.</p>`,async f=>{const v=Object.fromEntries(f);if(v.newPassword!==v.confirmPassword)throw Error('Las contraseñas nuevas no coinciden.');await mutate({action:'user.password.reset',id,...v});toast('Contraseña actualizada.');});
}
function enrollmentModal(id){
 const t=teachers.find(x=>x.id===id);if(!t)return;
 const roster=students.filter(x=>x.program===t.program&&x.semester===t.semester);
 modal('Matricular estudiantes en la clase',`<p><strong>${esc(t.subject)}</strong> · ${esc(t.name)}<br>${esc(t.program)} · Semestre ${esc(t.semester)}</p><p>Selecciona los estudiantes que pertenecen a esta clase. Desmarcar retira la matrícula y conserva las asistencias anteriores.</p><div style="max-height:330px;overflow:auto">${roster.map(x=>`<label style="display:flex;gap:12px;align-items:center"><input type="checkbox" name="studentIds" value="${esc(x.id)}" style="width:auto" ${enrollments.some(e=>e.teacher_id===id&&e.student_id===x.id)?'checked':''}>${esc(x.id+' · '+x.name)}</label>`).join('')||'<p>No hay estudiantes de este programa y semestre. Regístralos primero en Estudiantes.</p>'}</div>`,async f=>{await mutate({action:'enrollment.save',teacherId:id,studentIds:f.getAll('studentIds')});toast('Matrícula de la clase actualizada.');});
}

function auditPage(){return head('Bitácora de cambios','Registro de operaciones realizadas en el sistema.')+`<div class="card"><div class="tablewrap"><table><thead><tr><th>Fecha y hora</th><th>Usuario</th><th>Operación</th><th>Registro</th></tr></thead><tbody>${audit.map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString('es-PE',{timeZone:'America/Lima'}))}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.target)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Aún no hay cambios registrados.</td></tr>'}</tbody></table></div><p class="hint">Se muestran las últimas 100 operaciones.</p></div>`}
function renderStudent(page){
 if(page==='attendance'){$('content').innerHTML=head('Mis asistencias','Historial personal de marcaciones.')+`<div class="card">${attendanceTable(attendance)}</div>`;return}
 const s=students[0];$('content').innerHTML=head('Mis clases y asistencia',`${esc(s.name)} · ${esc(s.program)} · Semestre ${esc(s.semester)}`)+`<div class="card"><h3>Clases disponibles para inscribirme</h3><p>Elige las clases de tu carrera y semestre. Después de inscribirte podrás marcar asistencia durante su horario.</p><button class="secondary" id="refreshclasses">Actualizar clases</button></div><div class="report-grid">${availableClasses.map(t=>`<div class="card"><h3>${esc(t.subject)}</h3><p>Docente: ${esc(t.name)}</p><p>${esc(t.day)} · ${esc(t.start)} – ${esc(t.end)}</p><button type="button" class="primary" data-selfenroll="${esc(t.id)}">Inscribirme en esta clase</button></div>`).join('')||'<div class="card">No hay nuevas clases disponibles de tu carrera y semestre con docente activo.</div>'}</div><div class="card"><h3>Mis clases inscritas</h3>${enrolledClasses.length?`<ul>${enrolledClasses.map(t=>`<li><strong>${esc(t.subject)}</strong> · ${esc(t.name)} · ${esc(t.day)} ${esc(t.start)}–${esc(t.end)}</li>`).join('')}</ul>`:'<p>Todavía no estás inscrito en una clase. Selecciona una de las opciones de arriba.</p>'}</div><div class="card"><h3>Registrar asistencia — clases de hoy</h3><p>No necesitas huella ni código. El botón registra tu asistencia como Presente durante el horario de tu clase.</p><p class="hint">Horario del servidor: ${esc(new Date(serverTime).toLocaleString('es-PE',{timeZone:'America/Lima'}))}.</p></div><div class="report-grid">${myClasses.map(t=>`<div class="card"><h3>${esc(t.subject)}</h3><p>${esc(t.name)}</p><p>${esc(t.start)} – ${esc(t.end)}</p>${t.status?`<span class="badge">Asistencia registrada: ${esc(t.status)}</span>`:`<button class="primary" data-selfmark="${esc(t.id)}">Registrar mi asistencia</button>`}</div>`).join('')||'<div class="card">No tienes clases inscritas para hoy. Puedes inscribirte arriba; la asistencia estará disponible el día de cada clase.</div>'}</div>`;
 $('refreshclasses').onclick=async()=>{try{await reload();render('dashboard')}catch(e){toast(e.message)}};
 document.querySelectorAll('[data-selfenroll]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await mutate({action:'enrollment.self',teacherId:b.dataset.selfenroll});toast('Inscripción completada. Revisa tus clases inscritas.');}catch(e){toast(e.message)}finally{b.disabled=false}});
 document.querySelectorAll('[data-selfmark]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await mutate({action:'attendance.self',teacherId:b.dataset.selfmark});toast('Tu asistencia se registró correctamente.')}catch(e){toast(e.message)}finally{b.disabled=false}});
}

$('change-password-login').onclick=passwordModal;$('change-password-account').onclick=passwordModal;
enter();

function showCredentials(c){document.querySelector('.credentials')?.remove();const e=document.createElement('div');e.className='card credentials';e.style.cssText='background:#e7f6f1;border:1px solid #9bddca;margin:20px 0';e.innerHTML=`<h3>${c.studentCode?'Datos del estudiante / código de verificación':'Credenciales generadas automáticamente'}</h3><p class="hint">Guarda estos datos ahora. Se muestran una sola vez.</p>${c.studentCode?`<p>Código institucional: <strong>${esc(c.studentId)}</strong></p>${Number.isInteger(c.enrolledClasses)?`<p>Clases matriculadas: <strong>${c.enrolledClasses}</strong></p>`:''}<p>Código de asistencia: <strong>${esc(c.studentCode)}</strong></p>`:`<p>Usuario: <strong>${esc(c.username)}</strong></p><p>Contraseña: <strong>${esc(c.password)}</strong></p>`}<button class="secondary" type="button">Ya guardé los datos</button>`;e.querySelector('button').onclick=()=>e.remove();($('app').style.display==='block'?$('content'):$('loginform')).append(e)}
</script><script src="assets/accessibility.js?v=20261023" defer></script></body></html>
